function mutateReceiptStateTransition(transition, fixture) {
  let result = transition;
  if (fixture.tamperTransitionProofHash) {
    result = { ...result, proofHash: 'sha256:tampered' };
  }
  if (fixture.forceTransitionBlocked) {
    result = {
      ...result,
      status: 'blocked_receipt_transition',
      ready: false,
      blockers: [
        ...(result.blockers || []),
        { level: 'error', code: 'fixture_forced_transition_blocked', notes: null },
      ],
    };
  }
  if (fixture.tamperTransitionToStage) {
    result = {
      ...result,
      result: {
        ...result.result,
        stage: fixture.tamperTransitionToStage,
        requestedStage: fixture.tamperTransitionToStage,
        decision: {
          ...result.result?.decision,
          toStage: fixture.tamperTransitionToStage,
        },
      },
    };
  }
  return result;
}

function materializeReceiptStateTransitionInboxFixture(
  fixture,
  channelStateProofInboxFixtures,
  adapterReceiptInboxFixtures,
  channelStateProofFixtures,
  adapterReceiptFixtures,
  adapterHandoffOutboxFixtures,
  externalActionLedgerFixtures,
  actionManifestFixtures,
) {
  const proofInboxFixture = channelStateProofInboxFixtures.find((item) => item.name === fixture.proofInboxFixture);
  assert(proofInboxFixture, `receipt state transition inbox fixture ${fixture.name} references missing proof inbox fixture ${fixture.proofInboxFixture}`);
  const proofFixture = channelStateProofFixtures.find((item) => item.name === fixture.channelStateProofFixture);
  assert(proofFixture, `receipt state transition inbox fixture ${fixture.name} references missing proof fixture ${fixture.channelStateProofFixture}`);
  const { proof, transition } = materializeChannelStateProofFixture(
    proofFixture,
    adapterReceiptFixtures,
    actionManifestFixtures,
  );
  const receiptInboxFixture = adapterReceiptInboxFixtures.find((item) => item.name === proofInboxFixture.receiptInboxFixture);
  assert(receiptInboxFixture, `receipt state transition inbox fixture ${fixture.name} references missing receipt inbox fixture ${proofInboxFixture.receiptInboxFixture}`);
  const receiptInboxItem = materializeAdapterReceiptInboxFixture(
    receiptInboxFixture,
    adapterHandoffOutboxFixtures,
    adapterReceiptFixtures,
    externalActionLedgerFixtures,
    actionManifestFixtures,
    channelStateProofFixtures,
  );
  const receiptFixture = adapterReceiptFixtures.find((item) => item.name === (proofFixture.adapterReceiptFixture || proofInboxFixture.adapterReceiptFixture));
  assert(receiptFixture, `receipt state transition inbox fixture ${fixture.name} references missing receipt fixture`);
  const receipt = materializeAdapterReceiptFixture(receiptFixture, actionManifestFixtures);
  const proofInboxItem = buildChannelStateProofInboxItem({
    receiptInboxItem,
    proof,
    receipt,
    receivedBy: 'selftest.receipt-state-transition-inbox.proof',
  });

  return buildReceiptStateTransitionInboxItem({
    proofInboxItem,
    proof,
    transition: mutateReceiptStateTransition(transition, fixture),
    receivedBy: 'selftest.receipt-state-transition-inbox',
  });
}

