const humanFeedbackFixtures = JSON.parse(fs.readFileSync(new URL('../fixtures/human-feedback-contract-fixtures.json', import.meta.url), 'utf8'));
for (const fixture of humanFeedbackFixtures) {
  const contract = createHumanFeedbackRevisionContract(fixture.contract);
  const validation = validateHumanFeedbackRevisionContract(contract, {
    externalAction: fixture.externalAction || EXTERNAL_ACTIONS.NONE,
  });
  assert(
    validation.ok === fixture.expectedOk,
    `human feedback fixture ${fixture.name} expected ok=${fixture.expectedOk}, got ${validation.ok}: ${JSON.stringify(validation.blockers)}`,
  );
  const blockerCodes = validation.blockers.map((blocker) => blocker.code);
  for (const code of fixture.expectedBlockers || []) {
    assert(blockerCodes.includes(code), `human feedback fixture ${fixture.name} expected blocker ${code}`);
  }
}

