const integrationGateLockTestRoot = fs.mkdtempSync('/tmp/design-production-core-gate-lock-');
let firstGateLock = null;
let staleGateLock = null;
let recoveredGateLock = null;
try {
  const lockDir = `${integrationGateLockTestRoot}/integration-gate.lock`;
  firstGateLock = acquireIntegrationDependencyGateLock({
    lockDir,
    pid: process.pid,
    startedAt: '2026-06-14T00:00:00.000Z',
  });
  assert(firstGateLock.ok === true, 'integration dependency gate lock should acquire an empty lock');
  const busyGateLock = acquireIntegrationDependencyGateLock({
    lockDir,
    pid: process.pid + 1,
    startedAt: '2026-06-14T00:00:01.000Z',
  });
  assert(busyGateLock.ok === false, 'integration dependency gate lock should block overlapping live owners');
  assert(
    busyGateLock.blockers.some((blocker) => blocker.code === 'integration_dependency_gate_already_running'),
    'integration dependency gate lock should expose an overlapping-run blocker',
  );
  assert(releaseIntegrationDependencyGateLock(firstGateLock) === true, 'integration dependency gate lock should release the owning lock');
  firstGateLock = null;
  const staleLockDir = `${integrationGateLockTestRoot}/stale-integration-gate.lock`;
  staleGateLock = acquireIntegrationDependencyGateLock({
    lockDir: staleLockDir,
    pid: 999999999,
    startedAt: '2026-06-13T00:00:00.000Z',
  });
  assert(staleGateLock.ok === true, 'integration dependency gate lock should create a stale dead-pid fixture');
  recoveredGateLock = acquireIntegrationDependencyGateLock({
    lockDir: staleLockDir,
    pid: process.pid,
    startedAt: '2026-06-14T00:00:02.000Z',
  });
  staleGateLock = null;
  assert(recoveredGateLock.ok === true, 'integration dependency gate lock should recover stale dead-pid locks');
  assert(releaseIntegrationDependencyGateLock(recoveredGateLock) === true, 'integration dependency gate lock should release recovered stale locks');
  recoveredGateLock = null;
} finally {
  for (const lock of [recoveredGateLock, staleGateLock, firstGateLock]) {
    releaseIntegrationDependencyGateLock(lock);
  }
}

