function rewriteReportIdentityAsHumanFeedbackAlias(report) {
  report.handoff.action = 'consumer-feedback-message';
  report.handoff.productLineId = 'consumer_feedback';
  report.handoff.workflowId = 'consumer-feedback';
  const manifest = report.handoffSnapshots?.manifest;
  if (manifest) {
    manifest.action = 'consumer-feedback-message';
    manifest.productLineId = 'consumer_feedback';
    manifest.workflowId = 'consumer-feedback';
    manifest.payload = {
      ...(manifest.payload || {}),
    };
    if (Object.hasOwn(manifest.payload, 'action')) manifest.payload.action = 'consumer-feedback-message';
    if (Object.hasOwn(manifest.payload, 'productLineId')) manifest.payload.productLineId = 'consumer_feedback';
    if (Object.hasOwn(manifest.payload, 'workflowId')) manifest.payload.workflowId = 'consumer-feedback';
  }
  const preview = report.handoffSnapshots?.preview;
  if (preview) {
    preview.payload = {
      ...(preview.payload || {}),
    };
    if (Object.hasOwn(preview.payload, 'action')) preview.payload.action = 'consumer-feedback-message';
    if (Object.hasOwn(preview.payload, 'productLineId')) preview.payload.productLineId = 'consumer_feedback';
    if (Object.hasOwn(preview.payload, 'workflowId')) preview.payload.workflowId = 'consumer-feedback';
  }
}
