function recomputeSdkSnapshotHashes(report) {
  const manifest = report?.handoffSnapshots?.manifest;
  if (manifest) {
    const manifestHash = computeChannelActionManifestHash(manifest);
    manifest.manifestHash = manifestHash;
    manifest.hash = manifestHash;
    report.hashBinding.requiredHashes.manifestHash = manifestHash;
  }
  const preview = report?.handoffSnapshots?.preview;
  if (preview) {
    const previewHash = computeAdapterRunPreviewHash(preview);
    preview.previewHash = previewHash;
    preview.hash = previewHash;
    report.hashBinding.requiredHashes.previewHash = previewHash;
  }
}

