function rewriteSdkReportAsHumanFeedbackMessage(report) {
  const messagePreview = 'Human feedback revision approved; proceed with the exact reviewed change only.';
  const messagePreviewHash = computeCustomerMessagePreviewHash(messagePreview);
  report.handoff.actionId = 'hepta.customerMessagePreview';
  report.handoff.action = EXTERNAL_ACTIONS.CUSTOMER_MESSAGE;
  report.handoff.productLineId = PRODUCT_LINE_IDS.HUMAN_FEEDBACK;
  report.handoff.workflowId = PRODUCT_LINE_IDS.HUMAN_FEEDBACK;
  report.handoff.humanFeedbackRevisionContractHash = null;
  report.handoff.messagePreview = messagePreview;
  report.handoff.messagePreviewHash = messagePreviewHash;
  report.hashBinding.requiredHashes.messagePreviewHash = messagePreviewHash;
  report.hashBinding.requiredHashes.humanFeedbackRevisionContractHash = null;
  const manifest = report.handoffSnapshots?.manifest;
  if (manifest) {
    manifest.actionId = report.handoff.actionId;
    manifest.action = report.handoff.action;
    manifest.productLineId = report.handoff.productLineId;
    manifest.workflowId = report.handoff.workflowId;
    manifest.payload = {
      ...(manifest.payload || {}),
      action: report.handoff.action,
      productLineId: report.handoff.productLineId,
      workflowId: report.handoff.workflowId,
      messagePreview,
      messagePreviewHash,
      humanFeedbackRevisionContractHash: null,
    };
  }
  const preview = report.handoffSnapshots?.preview;
  if (preview) {
    preview.payload = {
      ...(preview.payload || {}),
      action: report.handoff.action,
      productLineId: report.handoff.productLineId,
      workflowId: report.handoff.workflowId,
      messagePreview,
      messagePreviewHash,
      humanFeedbackRevisionContractHash: null,
    };
    preview.adapter = {
      ...(preview.adapter || {}),
      requiredHashes: {
        ...(preview.adapter?.requiredHashes || {}),
        messagePreviewHash,
        humanFeedbackRevisionContractHash: null,
      },
    };
  }
  recomputeSdkSnapshotHashes(report);
}

function materializeAdapterRunnerSdkFixture(fixture) {
  const report = JSON.parse(JSON.stringify(lookupFixtureValue(
    adapterDispatchReadinessReportFixtures,
    adapterDispatchReadinessReports,
    fixture.readinessReportFixture,
    'adapter runner sdk fixture',
    fixture.name,
  )));
  if (fixture.payloadMode === 'missing_approval_hash') {
    delete report.hashBinding.requiredHashes.approvalHash;
  }
  if (fixture.payloadMode === 'missing_report_hash') {
    delete report.reportHash;
    delete report.hash;
  }
  if (fixture.payloadMode === 'missing_runner_location') {
    delete report.runner.runnerLocation;
  }
  if (fixture.payloadMode === 'core_local_runner_location') {
    report.runner.runnerLocation = './src';
  }
  if (fixture.payloadMode === 'unsafe_readiness') {
    report.safety.executesExternalAction = true;
  }
  if (fixture.payloadMode === 'missing_handoff_snapshots') {
    report.handoffSnapshots = null;
  }
  if (fixture.payloadMode === 'tampered_manifest_snapshot') {
    report.handoffSnapshots.manifest.payload = {
      ...report.handoffSnapshots.manifest.payload,
      artifactCount: (report.handoffSnapshots.manifest.payload?.artifactCount || 0) + 1,
    };
  }
  if (fixture.payloadMode === 'human_feedback_missing_contract_hash') {
    rewriteSdkReportAsHumanFeedbackMessage(report);
  }
  return buildAdapterRunnerSdkContract({
    readinessReport: report,
    actor: 'selftest.adapter-runner-sdk',
    createdAt: new Date(0).toISOString(),
  });
}
