  assert(preparePhase.requiredInputs.includes('dryRunReplayEvidence'), `adapter runner sdk fixture ${fixture.name} prepare phase must require dry-run replay input`);
  assert(executePhase.requiredInputs.includes('platformStateSnapshotHash'), `adapter runner sdk fixture ${fixture.name} execute phase must require platform snapshot hash`);
