    assert(contract.acceptanceCriteria.includes('external_runner_binds_dry_run_replay_before_prepare_or_execute'), `adapter runner sdk fixture ${fixture.name} expected dry-run replay acceptance criteria`);
    assert(contract.acceptanceCriteria.includes('external_runner_records_adapter_receipt_for_success_failure_or_cancel'), `adapter runner sdk fixture ${fixture.name} expected receipt acceptance criteria`);
    assert(contract.acceptanceCriteria.includes('external_runner_binds_receipt_to_snapshot_and_replay_hashes'), `adapter runner sdk fixture ${fixture.name} expected receipt snapshot/replay binding criteria`);
    assert(contract.acceptanceCriteria.includes('external_runner_supplies_action_specific_receipt_and_state_proof_fields'), `adapter runner sdk fixture ${fixture.name} expected action-specific evidence criteria`);
