function lookupFixtureValue(fixtureRows, valueRows, name, label, ownerName) {
  const index = fixtureRows.findIndex((item) => item.name === name);
  assert(index >= 0, `${label} ${ownerName} references missing fixture ${name}`);
  return valueRows[index];
}

function lookupFixtureValueMap(fixtureRows, valueRows, names, label, ownerName) {
  return Object.fromEntries(Object.entries(names || {}).map(([key, name]) => [
    key,
    lookupFixtureValue(fixtureRows, valueRows, name, label, ownerName),
  ]));
}

